package com.siam.deviceinfo.adapter; import android.view.*;import android.widget.*;import android.content.*;import java.util.*;import com.siam.deviceinfo.R;
public class InfoAdapter extends BaseAdapter {Context c;List<Map.Entry<String,String>> items;public InfoAdapter(Context c,Map<String,String>m){this.c=c;items=new ArrayList<>(m.entrySet());}public int getCount(){return items.size();}public Object getItem(int p){return items.get(p);}public long getItemId(int p){return p;}public View getView(int p,View v,android.view.ViewGroup g){if(v==null)v=LayoutInflater.from(c).inflate(R.layout.item_info,g,false);((TextView)v.findViewById(R.id.info_label)).setText(items.get(p).getKey());((TextView)v.findViewById(R.id.info_value)).setText(items.get(p).getValue());return v;}}
